package solution

import (
	"reflect"
	"testing"
)

func TestAccountRegistrationNormalizationAndFailedIDConsumption(t *testing.T) {
	secret := []byte("directory secret")
	store, err := NewAccountStore(secret)
	if err != nil {
		t.Fatalf("NewAccountStore: %v", err)
	}
	secret[0] ^= 0xff

	if _, err := store.Register(" ", "x@example.com", "12345678"); err == nil {
		t.Fatal("Register accepted whitespace-only name")
	}
	if _, err := store.Register("Name", "\u2003", "12345678"); err == nil {
		t.Fatal("Register accepted whitespace-only email")
	}
	if _, err := store.Register("Name", "x@example.com", "1234567"); err == nil {
		t.Fatal("Register accepted a seven-byte password")
	}

	account, err := store.Register("  Alice Smith\u00a0", " Alice@Example.COM ", "12345678")
	if err != nil {
		t.Fatalf("Register valid account: %v", err)
	}
	want := PublicAccount{ID: "u1", Name: "Alice Smith", Email: "alice@example.com"}
	if account != want {
		t.Fatalf("account = %+v; want %+v", account, want)
	}
	if _, err := store.Register("Other", "ALICE@example.com", "abcdefgh"); err == nil {
		t.Fatal("Register accepted duplicate normalized email")
	}
	second, err := store.Register("Bob", "bob@example.com", "abcdefgh")
	if err != nil || second.ID != "u2" {
		t.Fatalf("second successful registration = %+v, %v; want ID u2", second, err)
	}
}

func TestAccountAuthenticationAndVerification(t *testing.T) {
	store, err := NewAccountStore([]byte("secret"))
	if err != nil {
		t.Fatal(err)
	}
	account, err := store.Register("Alice", "Alice@Example.com", "password")
	if err != nil {
		t.Fatal(err)
	}
	if _, err := store.Authenticate("alice@example.com", "wrongpass"); err == nil {
		t.Fatal("Authenticate accepted wrong password")
	}
	if _, err := store.Authenticate("missing@example.com", "password"); err == nil {
		t.Fatal("Authenticate accepted missing user")
	}
	token1, err := store.Authenticate("  ALICE@EXAMPLE.COM\u2003", "password")
	if err != nil {
		t.Fatalf("Authenticate normalized email: %v", err)
	}
	token2, err := store.Authenticate("alice@example.com", "password")
	if err != nil || token1 != token2 {
		t.Fatalf("authentication is not deterministic: %q and %q, err %v", token1, token2, err)
	}
	got, err := store.Verify(token1)
	if err != nil || got != account {
		t.Fatalf("Verify = %+v, %v; want %+v", got, err, account)
	}

	for _, malformed := range []string{"", "%%%", token1 + "="} {
		if _, err := store.Verify(malformed); err == nil {
			t.Fatalf("Verify accepted malformed token %q", malformed)
		}
	}
	altered := []byte(token1)
	if altered[0] == 'A' {
		altered[0] = 'B'
	} else {
		altered[0] = 'A'
	}
	if _, err := store.Verify(string(altered)); err == nil {
		t.Fatal("Verify accepted altered token")
	}
}

func TestAccountUnknownSignedTokenAndSecretCopy(t *testing.T) {
	secret := []byte("shared secret")
	first, _ := NewAccountStore(secret)
	second, _ := NewAccountStore(secret)
	_, _ = first.Register("One", "one@example.com", "password")
	_, _ = first.Register("Two", "two@example.com", "password")
	_, _ = second.Register("One", "one@example.com", "password")
	token, err := first.Authenticate("two@example.com", "password")
	if err != nil {
		t.Fatal(err)
	}
	if _, err := second.Verify(token); err == nil {
		t.Fatal("Verify accepted validly signed token for unknown account")
	}

	copiedSecret := []byte("copy me")
	store, _ := NewAccountStore(copiedSecret)
	_, _ = store.Register("Name", "n@example.com", "password")
	tok, err := store.Authenticate("n@example.com", "password")
	if err != nil {
		t.Fatal(err)
	}
	copiedSecret[0] = 'X'
	if _, err := store.Verify(tok); err != nil {
		t.Fatalf("store retained caller's secret slice: %v", err)
	}
}

func TestAccountFindByNameSortingAndReturnedValueIsolation(t *testing.T) {
	store, _ := NewAccountStore([]byte("secret"))
	for i := 1; i <= 10; i++ {
		name := "Other"
		if i == 1 || i == 2 || i == 10 {
			name = "Same"
		}
		email := "user" + string(rune('a'+i-1)) + "@example.com"
		if _, err := store.Register(name, email, "password"); err != nil {
			t.Fatal(err)
		}
	}
	got := store.FindByName("Same")
	ids := make([]string, len(got))
	for i := range got {
		ids[i] = got[i].ID
	}
	want := []string{"u1", "u10", "u2"}
	if !reflect.DeepEqual(ids, want) {
		t.Fatalf("FindByName IDs = %v; want bytewise order %v", ids, want)
	}
	if extra := store.FindByName("same"); len(extra) != 0 {
		t.Fatalf("FindByName was not exact: %+v", extra)
	}
	got[0].Name = "mutated"
	again := store.FindByName("Same")
	if len(again) != 3 || again[0].Name != "Same" {
		t.Fatalf("returned account exposed store state: %+v", again)
	}
}

func TestAccountStoreRejectsEmptySecret(t *testing.T) {
	if store, err := NewAccountStore(nil); err == nil || store != nil {
		t.Fatalf("NewAccountStore(nil) = %v, %v; want nil, error", store, err)
	}
}

package solution

import "testing"

func TestReviewAlteredToken0102(t *testing.T) {
	s, err := NewAccountStore([]byte("review-secret"))
	if err != nil { t.Fatal(err) }
	if _, err = s.Register("A", "a@example.test", "password1"); err != nil { t.Fatal(err) }
	token, err := s.Authenticate("a@example.test", "password1")
	if err != nil { t.Fatal(err) }
	if _, err = s.Verify(token); err != nil { t.Fatal(err) }
	if account, err := s.Verify(token + "\n"); err == nil {
		t.Fatalf("altered token with newline accepted: %+v", account)
	}
}

